    (2, '3235100377', 2081, '53121721', '2025-10-13', 2620, null, 7.7, 1, 'FE-5224 FE-5223', 'OLM', '2025-10-23 12:58:29', 'I', null, null, false, 274, '4164', false, null, null, null, 1, 'A', '2025-10-13 00:00:00'),
    (2, '3235100377', 2084, '500218345', '2025-10-13', 810, null, 7.7, 1, 'FE-5029', 'OLM', '2025-10-23 13:08:30', 'I', null, null, false, 308, '4168', false, null, null, null, 1, 'A', '2025-10-13 00:00:00'),
    (2, '3235100377', 2086, '7416169', '2025-10-13', 631, null, 7.7, 1, 'FE-5183', 'OLM', '2025-10-23 13:12:27', 'I', null, null, false, 306, '4170', false, null, null, null, 1, 'A', '2025-10-13 00:00:00'),
    (2, '206-131947-7', 2063, '4739614', '2025-10-14', 9630, null, 7.7, 1, 'FE-5037 FE-5041', 'OLM', '2025-10-21 15:21:56', 'I', null, null, false, 287, '4189', false, null, null, null, 20, 'A', '2025-10-14 00:00:00'),
    (2, '206-131947-7', 2067, '23321544', '2025-10-14', 1200, null, 7.7, 1, 'FE-5237', 'OLM', '2025-10-21 15:37:46', 'I', null, null, false, 21, '4165', false, null, null, null, 20, 'A', '2025-10-14 00:00:00'),
    (2, '206-131947-7', 2093, '11405334', '2025-10-15', 2300, null, 7.7, 1, 'FE-5248', 'OLM', '2025-10-23 18:38:02', 'I', null, null, false, 4, '4169', false, null, null, null, 20, 'A', '2025-10-15 00:00:00')) as x(loc, cuenta, documento, numero, fecha, monto, monto_mi, cambio, moneda_int, descripcion, emisor, f_ingreso, conciliado, f_concilia,
      transaccion, varios, cliente, recibo, caja_chica, depositante, usr_mod, f_mod, banco, estatus, fecha_ant)
    order by loc, fecha, documento loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_cb := null;
    select cb.id, cb.moneda_id into v_cb from public.cuentas_bancarias cb where cb.localidad_id = v_loc and cb.numero = r.cuenta::text;
    if v_cb.id is null then c_s := c_s + 1; raise notice 'Depósito % (3-0%): no tiene cuenta bancaria o no existe (%).', r.documento, r.loc, coalesce(r.cuenta::text, 'sin cuenta'); continue; end if;
    -- En las cuentas de dólares el MONTO viene en quetzales: el valor en US$ es MONTO_MI o MONTO / VALOR_CAMBIO.
    v_usdcta := v_cb.moneda_id = v_usd;
    v_cambio := case when v_usdcta and coalesce(r.cambio::numeric, 0) > 0 then r.cambio::numeric else 1 end;
    v_valor := case when v_usdcta then coalesce(r.monto_mi::numeric, round(r.monto::numeric / v_cambio, 2)) else r.monto::numeric end;
    v_id := null;
    select id into v_id from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'DEPOSITO' and deposito_anterior = r.documento;
    v_nom := case when r.cliente is not null then (select coalesce(nombre, razon_social) from public.clientes where localidad_id = v_loc and codigo::text = r.cliente::text limit 1) end;
    v_tr_id := null; v_tr_op := null;
    select id, tipo_operacion into v_tr_id, v_tr_op from public.transacciones_contables where localidad_id = v_loc and numero = r.transaccion::integer and r.transaccion::integer <> 0;
    if v_id is null then
      select coalesce(max(folio), 0) + 1 into v_folio from public.movimientos_bancarios where localidad_id = v_loc and tipo = 'DEPOSITO';
      insert into public.movimientos_bancarios (organizacion_id, localidad_id, cuenta_bancaria_id, tipo, folio, numero_documento, fecha, moneda_id, tipo_cambio,
        valor, valor_ml, valor_cuenta, estado, usuario, fecha_operacion, deposito_anterior, origen_anterior)
      values (v_org, v_loc, v_cb.id, 'DEPOSITO', v_folio, coalesce(r.numero::text, r.documento::text), r.fecha::date, v_gtq, 1, v_valor, v_valor, v_valor, 'ACTIVO',
        coalesce(upper(r.emisor::text), 'SISTEMA ANTERIOR'), coalesce(r.f_ingreso::timestamp, r.fecha::timestamp)::timestamptz, r.documento, 'MIGRADO')
      returning id into v_id;
      c_n := c_n + 1;
    else
      c_a := c_a + 1;
    end if;
    update public.movimientos_bancarios set cuenta_bancaria_id = v_cb.id, numero_documento = coalesce(r.numero::text, r.documento::text), fecha = r.fecha::date,
      moneda_id = case when v_usdcta then v_usd else v_gtq end, tipo_cambio = v_cambio, valor = v_valor, valor_ml = round(v_valor * v_cambio, 2), valor_cuenta = v_valor,
      descripcion = nullif(trim(r.descripcion::text), ''), deposito_por = nullif(trim(r.depositante::text), ''),
      tipo_tercero = case when coalesce(r.varios::boolean, false) then 'CLIENTES VARIOS' else 'CLIENTE' end,
      tercero_codigo = r.cliente::text, tercero_nombre = v_nom,
      transaccion_id = coalesce(v_tr_id, transaccion_id), tipo_operacion = coalesce(v_tr_op, tipo_operacion),
      conciliado = upper(coalesce(r.conciliado::text, '')) = 'C', fecha_conciliado = r.f_concilia::date,
      caja_chica = coalesce(r.caja_chica::boolean, false), clientes_varios = coalesce(r.varios::boolean, false),
      usuario = coalesce(upper(r.emisor::text), usuario), fecha_operacion = coalesce(r.f_ingreso::timestamp::timestamptz, fecha_operacion),
      origen_anterior = 'MIGRADO', deposito_anterior = r.documento, banco_anterior = r.banco::integer, estatus_anterior = r.estatus::text,
      conciliado_anterior = r.conciliado::text, moneda_integracion = r.moneda_int::integer, valor_cambio_anterior = r.cambio::numeric,
      transaccion_anterior = r.transaccion::integer, valor_mi = r.monto_mi::numeric, valor_anterior = r.monto::numeric, cuenta_bancaria_anterior = r.cuenta::text,
      cliente_codigo_anterior = r.cliente::integer, recibo_anterior = r.recibo::text, fecha_anterior = r.fecha_ant::timestamp,
      usuario_modifica_anterior = r.usr_mod::text, fecha_modifica_anterior = r.f_mod::date
    where id = v_id;
    -- Recibo físico del cliente (pestaña «Recibos físicos»): uno por depósito, por su valor.
    if r.recibo is not null then
      delete from public.movimiento_documentos where movimiento_id = v_id and tipo = 'RECIBO';
      insert into public.movimiento_documentos (movimiento_id, tipo, numero, tercero, nombre, valor, valor_ml, fecha, estado)
      values (v_id, 'RECIBO', r.recibo::text, r.cliente::text, v_nom, v_valor, round(v_valor * v_cambio, 2), r.fecha::date, 'EMITIDO');
      d_n := d_n + 1;
    end if;
  end loop;

  alter table public.movimientos_bancarios enable trigger movimientos_bancarios_preparar;
  alter table public.movimiento_lineas enable trigger movimiento_lineas_validar;

  raise notice '%', format('Depósitos: %s nuevos, %s actualizados, %s sin cuenta bancaria; %s recibos físicos. Detalle contable: %s líneas nuevas, %s actualizadas, %s sin depósito, %s sin cuenta.',
    c_n, c_a, c_s, d_n, l_n, l_a, l_s, l_c);
  if l_c > 0 then raise notice 'Cuentas que no existen en el catálogo de la localidad (líneas omitidas): %.', (select string_agg(distinct x, ', ') from unnest(v_faltan) x); end if;
end;
$migra$;

notify pgrst, 'reload schema';
